root=Path(__file__).resolve().parents[2];p=argparse.ArgumentParser();p.add_argument('--sdk',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=False);dst=a.output/'ritual-card-effects';shutil.copytree(root/'mods/ritual-card-effects',dst,ignore=shutil.ignore_patterns('__pycache__'));p=dst/'mod.c';before=p.read_text();after=before.replace('int MemoriesModInit(const MemoriesModHost *from, MemoriesMod *mod)','\n#include "queen_state_preview.h"\nint MemoriesModInit(const MemoriesModHost *from, MemoriesMod *mod)');needle='    selection_ready=1;selection_connect();\n    return 1;';assert needle in after;after=after.replace(needle,'    selection_ready=1;selection_connect();\n    if(!qs_init(mod)){shutdown();return 0;}\n    return 1;');p.write_text(after);shutil.copy2(root/'experiments/hal20-field-state/queen_state_preview.h',dst/'queen_state_preview.h');shutil.copy2(root/'experiments/hal20-field-state/queen_state_schema_v1.h',dst/'queen_state_schema_v1.h');(a.output/'queen.patch').write_text(''.join(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile='a/mod.c',tofile='b/mod.c')));q=subprocess.run(['python',str(a.sdk.resolve()/'tools/build_mod.py'),str(dst.resolve()),'--target','i386'],text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT);(a.output/'build.log').write_text(q.stdout);assert q.returncode==0,q.stdout;f=dst/'ritual-card-effects.o';(a.output/'BUILD.json').write_text(json.dumps(dict(scope='Queen logical capsule only; not collection/policy approval.',sha256=hashlib.sha256(f.read_bytes()).hexdigest(),bytes=f.stat().st_size),indent=2)+'\n')
